ALTER TABLE public.texas_cemeteries ADD COLUMN IF NOT EXISTS region text;

CREATE OR REPLACE FUNCTION public.cemetery_match_key(_name text, _city text)
RETURNS text LANGUAGE sql IMMUTABLE SET search_path = public AS $$
  SELECT btrim(regexp_replace(
    regexp_replace(
      regexp_replace(lower(coalesce(_name,'')), '\(.*?\)', ' ', 'g'),
      '[^a-z0-9]+', ' ', 'g'),
    '\y(cemetery|cemeteries|memorial|memory|park|parks|gardens|garden|funeral|homes|home|chapels|chapel|burial|mausoleum|the|of|and|at|inc|co)\y', ' ', 'g'))
    || '|' || btrim(lower(coalesce(_city,'')))
$$;

CREATE UNLOGGED TABLE public._cem_seed (name text, city text, region text, address text, lat numeric, lng numeric);

