INSERT INTO public.texas_cemeteries (name, city, region, address, latitude, longitude, auto_created)
SELECT DISTINCT ON (public.canonical_cemetery(s.name)) s.name, s.city, s.region, s.address, s.lat, s.lng, false
FROM public._cem_seed s
WHERE NOT EXISTS (
  SELECT 1 FROM public.texas_cemeteries t
  WHERE public.cemetery_match_key(t.name, t.city) = public.cemetery_match_key(s.name, s.city)
     OR public.canonical_cemetery(t.name) = public.canonical_cemetery(s.name)
);

UPDATE public.texas_cemeteries t
SET region = s.region
FROM public._cem_seed s
WHERE t.region IS NULL
  AND (public.cemetery_match_key(t.name, t.city) = public.cemetery_match_key(s.name, s.city)
       OR public.canonical_cemetery(t.name) = public.canonical_cemetery(s.name));

DROP TABLE public._cem_seed;

UPDATE public.texas_cemeteries SET region = CASE
  WHEN city ILIKE ANY (ARRAY['Dallas','Fort Worth','Arlington','Plano','Allen','McKinney','Irving','Garland','Mesquite','Rockwall','Rowlett','Frisco','Denton','Grand Prairie','Lancaster','Duncanville','Desoto','Seagoville','Carrollton','Flower Mound','Kennedale','Cleburne','Burleson','Euless','Colleyville','Lucas','Granbury','Sherman','Wichita Falls','Weatherford','Waxahachie','Corsicana','Greenville']) THEN 'Dallas–Fort Worth'
  WHEN city ILIKE ANY (ARRAY['Houston','Pasadena','Humble','Conroe','Tomball','Webster','Baytown','Pearland','Katy','Spring','Magnolia','The Woodlands','Sugar Land','Rosenberg','Galveston','Hitchcock','Dickinson','Clute','Porter','New Caney','Pinehurst','Highlands','East Bernard','League City','Friendswood','Cypress','Richmond','Angleton','Alvin','Texas City','La Porte','Deer Park','Channelview','Crosby']) THEN 'Greater Houston'
  WHEN city ILIKE ANY (ARRAY['Austin','Pflugerville','Round Rock','Cedar Park','Georgetown','Kyle','Lakeway','San Marcos','Taylor','Buda','Leander','Marble Falls','Burnet','Dripping Springs','Bastrop']) THEN 'Austin'
  WHEN city ILIKE ANY (ARRAY['San Antonio','New Braunfels','Seguin','Boerne','Schertz','Universal City','Converse','Helotes','Lockhart']) THEN 'San Antonio'
  WHEN city ILIKE ANY (ARRAY['Waco','Robinson','Killeen','Temple','Belton','College Station','Bryan','Copperas Cove','Harker Heights','Gatesville']) THEN 'Central Texas'
  WHEN city ILIKE ANY (ARRAY['Tyler','Longview','Marshall','Texarkana','Beaumont','Beamont','Orange','Port Neches','Groves','Nacogdoches','Lufkin','Canton','Palestine','Paris']) THEN 'East Texas'
  WHEN city ILIKE 'El Paso' THEN 'El Paso & West Texas'
  WHEN city ILIKE ANY (ARRAY['Corpus Christi','Robstown','Brownsville','McAllen','Mission','Pharr','Weslaco','La Feria','San Benito','Harlingen','Victoria','Yoakum','Laredo','Kingsville','Edinburg','Port Lavaca']) THEN 'South Texas'
  WHEN city ILIKE ANY (ARRAY['Lubbock','Amarillo','Midland','Odessa','Abilene','San Angelo','Big Spring','Plainview','Snyder']) THEN 'West & North Texas'
  ELSE 'Other Texas'
END
WHERE region IS NULL;

CREATE INDEX IF NOT EXISTS texas_cemeteries_region_idx ON public.texas_cemeteries (region);